
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_optpbe_vdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_optpbe_vdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.277247130560815e+00, -4.195164834711000e+00, -4.080245997244663e+00, -3.921262680291208e+00, -3.705070457750128e+00, -3.418285881208603e+00, -3.051218324386629e+00, -2.604956980789554e+00, -2.100666827251255e+00, -1.581088324475049e+00, -1.074028544730513e+00, -7.038557681391455e-01, -5.996733180165627e-01, -4.962849384630062e-01, -3.645344372946295e-01, -2.409553803474972e-01, -1.403439062992755e-01, -5.547517785400168e-02, -1.226621608790295e-02, -1.380714381046674e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


